package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

type MockRedis struct {
	mu   sync.Mutex
	data map[string]string
}

func NewMockRedis() *MockRedis {
	return &MockRedis{data: make(map[string]string)}
}

func (r *MockRedis) SetNX(ctx context.Context, key string, val string, ttl time.Duration) (bool, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	if _, exists := r.data[key]; exists {
		return false, nil // Ключ уже существует
	}
	r.data[key] = val
	return true, nil
}

type IdempotencyManager struct {
	redis *MockRedis
	ttl   time.Duration
}

func NewIdempotencyManager(redis *MockRedis, ttl time.Duration) *IdempotencyManager {
	return &IdempotencyManager{
		redis: redis,
		ttl:   ttl,
	}
}

func (m *IdempotencyManager) AcquireLock(ctx context.Context, userID, idempKey string) (bool, error) {
	redisKey := fmt.Sprintf("idemp:%s:%s", userID, idempKey)
	return m.redis.SetNX(ctx, redisKey, "STARTED", m.ttl)
}

func main() {
	redis := NewMockRedis()
	mgr := NewIdempotencyManager(redis, 24*time.Hour)
	ctx := context.Background()

	userID := "user-42"
	idempKey := "req-uuid-999-aaa"

	fmt.Println("=== 1. First HTTP Request arrival ===")
	acquired, err := mgr.AcquireLock(ctx, userID, idempKey)
	if err != nil {
		panic(err)
	}
	if acquired {
		fmt.Printf("[Idempotency Manager] Lock ACQUIRED for %s! Set status=STARTED. Executing handler...\n", idempKey)
	}

	fmt.Println("\n=== 2. Duplicate HTTP Request arrival (Client retry or race) ===")
	acquired, err = mgr.AcquireLock(ctx, userID, idempKey)
	if err != nil {
		panic(err)
	}
	if !acquired {
		fmt.Printf("[Idempotency Manager] Lock REJECTED (false) for %s! Key already exists in Redis.\n", idempKey)
	}
}

package main

import (
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sync"
	"time"
)

type RequestStatus string

const (
	StatusStarted   RequestStatus = "STARTED"
	StatusCompleted RequestStatus = "COMPLETED"
)

type IdempotencyStore struct {
	mu   sync.Mutex
	data map[string]RequestStatus
}

func (s *IdempotencyStore) TryStart(key string) (isNew bool, currentStatus RequestStatus) {
	s.mu.Lock()
	defer s.mu.Unlock()

	status, exists := s.data[key]
	if !exists {
		s.data[key] = StatusStarted
		return true, StatusStarted
	}
	return false, status
}

func (s *IdempotencyStore) Complete(key string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.data[key] = StatusCompleted
}

func HandlePayment(w http.ResponseWriter, r *http.Request, store *IdempotencyStore) {
	idempKey := r.Header.Get("Idempotency-Key")
	if idempKey == "" {
		http.Error(w, "Missing Idempotency-Key", http.StatusBadRequest)
		return
	}

	isNew, status := store.TryStart(idempKey)
	if !isNew {
		if status == StatusStarted {
			// Конкурентный дубликат: первичный запрос еще выполняется
			w.Header().Set("Retry-After", "2")
			w.WriteHeader(http.StatusConflict) // 409 Conflict
			_, _ = w.Write([]byte(`{"error": "Request is currently being processed, please retry later"}`))
			return
		}
		// Если статус уже COMPLETED, отдается сохраненный ответ
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"status": "ALREADY_COMPLETED"}`))
		return
	}

	// Имитация долгой бизнес-логики (например, обращение к эквайрингу)
	time.Sleep(50 * time.Millisecond)
	store.Complete(idempKey)

	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte(`{"status": "SUCCESS", "payment_id": "pay-777"}`))
}

func main() {
	store := &IdempotencyStore{data: make(map[string]RequestStatus)}
	key := "uuid-concurrent-100"

	// Запрос 1: начинает выполнение
	req1 := httptest.NewRequest(http.MethodPost, "/payments", nil)
	req1.Header.Set("Idempotency-Key", key)
	rr1 := httptest.NewRecorder()

	// Запрос 2: приходит пока Запрос 1 еще работает
	req2 := httptest.NewRequest(http.MethodPost, "/payments", nil)
	req2.Header.Set("Idempotency-Key", key)
	rr2 := httptest.NewRecorder()

	var wg sync.WaitGroup
	wg.Add(2)

	go func() {
		defer wg.Done()
		HandlePayment(rr1, req1, store)
	}()

	// Даем первому запросу захватить лок
	time.Sleep(10 * time.Millisecond)

	go func() {
		defer wg.Done()
		HandlePayment(rr2, req2, store)
	}()

	wg.Wait()

	fmt.Printf("Request 1 Response Code: %d, Body: %s\n", rr1.Code, rr1.Body.String())
	fmt.Printf("Request 2 Response Code: %d, Body: %s (Retry-After: %s)\n",
		rr2.Code, rr2.Body.String(), rr2.Header().Get("Retry-After"))
}

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sync"
	"time"
)

type CachedResponse struct {
	StatusCode int               `json:"status_code"`
	Headers    map[string]string `json:"headers"`
	Body       string            `json:"body"`
}

type IdempotencyService struct {
	mu    sync.Mutex
	cache map[string]string // key -> JSON(CachedResponse)
}

func NewIdempotencyService() *IdempotencyService {
	return &IdempotencyService{cache: make(map[string]string)}
}

func (s *IdempotencyService) Save(key string, resp CachedResponse) {
	s.mu.Lock()
	defer s.mu.Unlock()
	bytes, _ := json.Marshal(resp)
	s.cache[key] = string(bytes)
}

func (s *IdempotencyService) Get(key string) (*CachedResponse, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	raw, exists := s.cache[key]
	if !exists {
		return nil, false
	}
	var resp CachedResponse
	_ = json.Unmarshal([]byte(raw), &resp)
	return &resp, true
}

func ProcessOrderAPI(w http.ResponseWriter, r *http.Request, idempSvc *IdempotencyService, dbHits *int) {
	idempKey := r.Header.Get("Idempotency-Key")

	// 1. Проверяем наличие кэшированного ответа
	if cached, found := idempSvc.Get(idempKey); found {
		fmt.Println(" -> [Cache HIT] Serving cached response directly from Redis! DB NOT TOUCHED.")
		for k, v := range cached.Headers {
			w.Header().Set(k, v)
		}
		w.Header().Set("X-Cache-Lookup", "HIT")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write([]byte(cached.Body))
		return
	}

	// 2. Первичный запрос: идем в БД
	*dbHits++
	fmt.Println(" -> [Cache MISS] Executing DB transaction (Insert Order #888)...")

	responseBody := `{"order_id": "ord-888", "status": "APPROVED", "amount": 2500}`
	cachedResp := CachedResponse{
		StatusCode: http.StatusCreated,
		Headers: map[string]string{
			"Content-Type": "application/json",
		},
		Body: responseBody,
	}

	// 3. Сохраняем результат в кэш
	idempSvc.Save(idempKey, cachedResp)

	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("X-Cache-Lookup", "MISS")
	w.WriteHeader(http.StatusCreated)
	_, _ = w.Write([]byte(responseBody))
}

func main() {
	idempSvc := NewIdempotencyService()
	dbHits := 0
	idempKey := "order-uuid-golden-555"

	fmt.Println("=== 1. First HTTP POST request ===")
	req1 := httptest.NewRequest(http.MethodPost, "/orders", nil)
	req1.Header.Set("Idempotency-Key", idempKey)
	w1 := httptest.NewRecorder()
	ProcessOrderAPI(w1, req1, idempSvc, &dbHits)
	fmt.Printf("HTTP Status: %d, Cache: %s, Body: %s\n",
		w1.Code, w1.Header().Get("X-Cache-Lookup"), w1.Body.String())

	fmt.Println("\n=== 2. Duplicate HTTP POST request (Network retry) ===")
	req2 := httptest.NewRequest(http.MethodPost, "/orders", nil)
	req2.Header.Set("Idempotency-Key", idempKey)
	w2 := httptest.NewRecorder()
	ProcessOrderAPI(w2, req2, idempSvc, &dbHits)
	fmt.Printf("HTTP Status: %d, Cache: %s, Body: %s\n",
		w2.Code, w2.Header().Get("X-Cache-Lookup"), w2.Body.String())

	fmt.Printf("\nVerification: Total Database Hits = %d (Expected: 1)\n", dbHits)
}

package main

import (
	"bytes"
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sync"
)

type CachedData struct {
	Code int
	Body string
}

type MemoryStore struct {
	mu    sync.Mutex
	cache map[string]CachedData
}

// Паттерн Response Recorder
type responseRecorder struct {
	http.ResponseWriter
	statusCode int
	body       *bytes.Buffer
}

func newResponseRecorder(w http.ResponseWriter) *responseRecorder {
	return &responseRecorder{
		ResponseWriter: w,
		statusCode:     http.StatusOK, // Дефолтный статус
		body:           &bytes.Buffer{},
	}
}

func (rec *responseRecorder) WriteHeader(code int) {
	rec.statusCode = code
	rec.ResponseWriter.WriteHeader(code)
}

func (rec *responseRecorder) Write(b []byte) (int, error) {
	rec.body.Write(b)                  // Записываем в буфер для кэша
	return rec.ResponseWriter.Write(b) // Отправляем в сокет клиенту
}

func IdempotencyMiddleware(store *MemoryStore) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			key := r.Header.Get("Idempotency-Key")
			if key == "" {
				next.ServeHTTP(w, r)
				return
			}

			store.mu.Lock()
			cached, exists := store.cache[key]
			store.mu.Unlock()

			if exists {
				w.Header().Set("X-Idempotent-Replay", "true")
				w.WriteHeader(cached.Code)
				_, _ = w.Write([]byte(cached.Body))
				return
			}

			// Оборачиваем в recorder
			rec := newResponseRecorder(w)
			next.ServeHTTP(rec, r)

			// Сохраняем успешные ответы
			if rec.statusCode >= 200 && rec.statusCode < 300 {
				store.mu.Lock()
				store.cache[key] = CachedData{
					Code: rec.statusCode,
					Body: rec.body.String(),
				}
				store.mu.Unlock()
			}
		})
	}
}

func main() {
	store := &MemoryStore{cache: make(map[string]CachedData)}

	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fmt.Println(" [Business Handler] Processing payment...")
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		_, _ = w.Write([]byte(`{"payment_status": "PAID"}`))
	})

	protectedHandler := IdempotencyMiddleware(store)(handler)

	key := "uuid-middleware-test-1"

	fmt.Println("=== Call 1: Original Request ===")
	req1 := httptest.NewRequest(http.MethodPost, "/pay", nil)
	req1.Header.Set("Idempotency-Key", key)
	rr1 := httptest.NewRecorder()
	protectedHandler.ServeHTTP(rr1, req1)
	fmt.Printf("Status: %d, Body: %s, Replayed: %s\n",
		rr1.Code, rr1.Body.String(), rr1.Header().Get("X-Idempotent-Replay"))

	fmt.Println("\n=== Call 2: Duplicate Request (Intercepted by Middleware) ===")
	req2 := httptest.NewRequest(http.MethodPost, "/pay", nil)
	req2.Header.Set("Idempotency-Key", key)
	rr2 := httptest.NewRecorder()
	protectedHandler.ServeHTTP(rr2, req2)
	fmt.Printf("Status: %d, Body: %s, Replayed: %s\n",
		rr2.Code, rr2.Body.String(), rr2.Header().Get("X-Idempotent-Replay"))
}

package main

import (
	"bytes"
	"fmt"
	"net/http"
	"net/http/httptest"
	"sync"
)

type Store struct {
	mu   sync.Mutex
	data map[string]string
}

func (s *Store) Set(key, val string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.data[key] = val
}

func (s *Store) Delete(key string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.data, key)
	fmt.Printf(" -> [Middleware Cleanup] Deleted key '%s' from Redis (Allowed retry)\n", key)
}

func (s *Store) Get(key string) (string, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	val, exists := s.data[key]
	return val, exists
}

type statusRecorder struct {
	http.ResponseWriter
	code int
	body *bytes.Buffer
}

func (r *statusRecorder) WriteHeader(code int) {
	r.code = code
	r.ResponseWriter.WriteHeader(code)
}

func (r *statusRecorder) Write(b []byte) (int, error) {
	r.body.Write(b)
	return r.ResponseWriter.Write(b)
}

func ResilientIdempotencyMiddleware(store *Store) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			key := r.Header.Get("Idempotency-Key")
			if key == "" {
				next.ServeHTTP(w, r)
				return
			}

			if cached, ok := store.Get(key); ok && cached != "STARTED" {
				w.WriteHeader(http.StatusOK)
				_, _ = w.Write([]byte(cached))
				return
			}

			// Бронируем ключ
			store.Set(key, "STARTED")

			rec := &statusRecorder{ResponseWriter: w, code: 200, body: &bytes.Buffer{}}

			// Защита от паники
			defer func() {
				if err := recover(); err != nil {
					store.Delete(key) // Удаляем ключ при панике
					http.Error(w, "Internal Server Error", http.StatusInternalServerError)
				}
			}()

			next.ServeHTTP(rec, r)

			// Если сервер вернул 5xx, удаляем ключ!
			if rec.code >= 500 {
				store.Delete(key)
			} else {
				// Успех -> сохраняем
				store.Set(key, rec.body.String())
			}
		})
	}
}

func main() {
	store := &Store{data: make(map[string]string)}
	attempts := 0

	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		attempts++
		if attempts == 1 {
			fmt.Println(" [Handler] Database connection timeout! Returning 500...")
			w.WriteHeader(http.StatusInternalServerError)
			_, _ = w.Write([]byte(`{"error": "db down"}`))
			return
		}
		fmt.Println(" [Handler] Database restored! Payment processed successfully.")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"status": "SUCCESS"}`))
	})

	app := ResilientIdempotencyMiddleware(store)(handler)
	key := "uuid-err-retry-777"

	fmt.Println("=== Attempt 1: Server fails with 500 ===")
	req1 := httptest.NewRequest(http.MethodPost, "/pay", nil)
	req1.Header.Set("Idempotency-Key", key)
	rr1 := httptest.NewRecorder()
	app.ServeHTTP(rr1, req1)
	fmt.Printf("Attempt 1 Status: %d\n", rr1.Code)

	fmt.Println("\n=== Attempt 2: Client retries with the EXACT SAME key ===")
	req2 := httptest.NewRequest(http.MethodPost, "/pay", nil)
	req2.Header.Set("Idempotency-Key", key)
	rr2 := httptest.NewRecorder()
	app.ServeHTTP(rr2, req2)
	fmt.Printf("Attempt 2 Status: %d, Body: %s\n", rr2.Code, rr2.Body.String())
}

