import (
	"context"
	"fmt"
	"sync"
	"time"
)

type TTLStore struct {
	mu   sync.Mutex
	data map[string]time.Time // key -> expiresAt
}

func (s *TTLStore) SetWithTTL(key string, ttl time.Duration) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.data[key] = time.Now().Add(ttl)
}

func (s *TTLStore) Exists(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	exp, exists := s.data[key]
	if !exists {
		return false
	}
	if time.Now().After(exp) {
		delete(s.data, key) // Lazy eviction
		return false
	}
	return true
}

func main() {
	store := &TTLStore{data: make(map[string]time.Time)}
	_ = context.Background()

	// Производственные константы
	lockTTL := 60 * time.Second     // Для статуса STARTED (защита от краша воркера)
	responseTTL := 24 * time.Hour   // Для кэша финального ответа

	fmt.Printf("Production Idempotency Configuration:\n")
	fmt.Printf(" - Lock Phase TTL:     %v (Auto-release if pod crashes)\n", lockTTL)
	fmt.Printf(" - Response Cache TTL: %v (Standard Retry Window)\n\n", responseTTL)

	// Тест с коротким TTL (50 миллисекунд)
	testKey := "idemp:user-1:uuid-ttl-test"
	store.SetWithTTL(testKey, 50*time.Millisecond)

	fmt.Println("=== Immediate Check ===")
	fmt.Printf("Key exists: %t (In-memory cached)\n", store.Exists(testKey))

	fmt.Println("\n=== Waiting for TTL Expiration (Sleep 70ms) ===")
	time.Sleep(70 * time.Millisecond)

	fmt.Printf("Key exists after TTL: %t (Garbage Collected automatically!)\n", store.Exists(testKey))
}

package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
)

func HashRequest(method, path string, body []byte) string {
	h := sha256.New()
	h.Write([]byte(method + ":" + path + ":"))
	h.Write(body)
	return hex.EncodeToString(h.Sum(nil))
}

type IdempRecord struct {
	RequestHash  string
	ResponseCode int
	ResponseBody string
}

type SecurityIdempotencyStore struct {
	mu      sync.Mutex
	records map[string]IdempRecord
}

func HandlePaymentSecure(w http.ResponseWriter, r *http.Request, bodyStr string, store *SecurityIdempotencyStore) {
	key := r.Header.Get("Idempotency-Key")
	currentHash := HashRequest(r.Method, r.URL.Path, []byte(bodyStr))

	store.mu.Lock()
	record, exists := store.records[key]
	if exists {
		store.mu.Unlock()
		// Проверка совпадения Payload
		if record.RequestHash != currentHash {
			w.WriteHeader(http.StatusUnprocessableEntity) // 422
			_, _ = w.Write([]byte(`{"error": "Idempotency key was previously used with a different request payload"}`))
			return
		}

		// Payload совпал -> отдаем кэшированный ответ
		w.WriteHeader(record.ResponseCode)
		_, _ = w.Write([]byte(record.ResponseBody))
		return
	}

	// Первичный запрос -> сохраняем хэш
	respBody := `{"status": "SUCCESS", "message": "Payment accepted"}`
	store.records[key] = IdempRecord{
		RequestHash:  currentHash,
		ResponseCode: http.StatusOK,
		ResponseBody: respBody,
	}
	store.mu.Unlock()

	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte(respBody))
}

func main() {
	store := &SecurityIdempotencyStore{records: make(map[string]IdempRecord)}
	key := "shared-user-key-001"

	fmt.Println("=== 1. Request 1: Pay 100 Rubles ===")
	body1 := `{"amount": 100, "recipient": "Alice"}`
	req1 := httptest.NewRequest(http.MethodPost, "/api/pay", strings.NewReader(body1))
	req1.Header.Set("Idempotency-Key", key)
	rr1 := httptest.NewRecorder()
	HandlePaymentSecure(rr1, req1, body1, store)
	fmt.Printf("Response 1 Code: %d, Body: %s\n", rr1.Code, rr1.Body.String())

	fmt.Println("\n=== 2. Request 2: RETRY Pay 100 Rubles (Exact same payload) ===")
	rr2 := httptest.NewRecorder()
	HandlePaymentSecure(rr2, req1, body1, store)
	fmt.Printf("Response 2 Code: %d, Body: %s (Idempotent Replay OK)\n", rr2.Code, rr2.Body.String())

	fmt.Println("\n=== 3. Request 3: TAMPERED PAYLOAD! Pay 5000 Rubles with SAME Key ===")
	body3 := `{"amount": 5000, "recipient": "Bob"}`
	req3 := httptest.NewRequest(http.MethodPost, "/api/pay", strings.NewReader(body3))
	req3.Header.Set("Idempotency-Key", key)
	rr3 := httptest.NewRecorder()
	HandlePaymentSecure(rr3, req3, body3, store)
	fmt.Printf("Response 3 Code: %d, Body: %s (ATTACK BLOCKED!)\n", rr3.Code, rr3.Body.String())
}

package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

type DBIdempRow struct {
	Key            string
	UserID         string
	RequestHash    string
	ResponseStatus int
	ResponseBody   string
	CreatedAt      time.Time
}

type PostgresMock struct {
	mu   sync.Mutex
	rows map[string]DBIdempRow // key: userID + ":" + key
}

func NewPostgresMock() *PostgresMock {
	return &PostgresMock{rows: make(map[string]DBIdempRow)}
}

// Эмуляция INSERT INTO idempotency_keys (...) ON CONFLICT DO NOTHING
func (db *PostgresMock) TryInsertKey(userID, key, hash string) bool {
	db.mu.Lock()
	defer db.mu.Unlock()

	compositeKey := userID + ":" + key
	if _, exists := db.rows[compositeKey]; exists {
		return false // ON CONFLICT DO NOTHING -> RowsAffected = 0
	}

	db.rows[compositeKey] = DBIdempRow{
		Key:         key,
		UserID:      userID,
		RequestHash: hash,
		CreatedAt:   time.Now().UTC(),
	}
	return true // Inserted -> RowsAffected = 1
}

func (db *PostgresMock) UpdateResponse(userID, key string, status int, body string) {
	db.mu.Lock()
	defer db.mu.Unlock()
	compositeKey := userID + ":" + key
	row := db.rows[compositeKey]
	row.ResponseStatus = status
	row.ResponseBody = body
	db.rows[compositeKey] = row
}

func (db *PostgresMock) GetRow(userID, key string) (DBIdempRow, bool) {
	db.mu.Lock()
	defer db.mu.Unlock()
	compositeKey := userID + ":" + key
	row, ok := db.rows[compositeKey]
	return row, ok
}

func ProcessBankingTransfer(db *PostgresMock, userID, key, hash string, amount int) (int, string) {
	// Шаг 1: Атомарная вставка в PostgreSQL
	inserted := db.TryInsertKey(userID, key, hash)
	if !inserted {
		// Ключ уже был -> читаем сохраненный ответ
		row, _ := db.GetRow(userID, key)
		fmt.Printf(" -> [Postgres] Key conflict! Returning cached result: %s\n", row.ResponseBody)
		return row.ResponseStatus, row.ResponseBody
	}

	// Шаг 2: Выполнение бизнес-транзакции
	fmt.Printf(" -> [Postgres] Fresh transaction! Debiting %d rubles from account...\n", amount)
