type ExpiringKeyRecord struct {
	Key          string
	ExpiresAt    time.Time
	ResponseJSON string
}

type DatabaseWithTTL struct {
	mu    sync.Mutex
	table map[string]ExpiringKeyRecord
}

func NewDatabaseWithTTL() *DatabaseWithTTL {
	return &DatabaseWithTTL{table: make(map[string]ExpiringKeyRecord)}
}

func (db *DatabaseWithTTL) Save(key string, responseJSON string, ttl time.Duration) {
	db.mu.Lock()
	defer db.mu.Unlock()

	db.table[key] = ExpiringKeyRecord{
		Key:          key,
		ExpiresAt:    time.Now().Add(ttl),
		ResponseJSON: responseJSON,
	}
}

func (db *DatabaseWithTTL) GetActive(key string) (string, bool) {
	db.mu.Lock()
	defer db.mu.Unlock()

	rec, exists := db.table[key]
	if !exists {
		return "", false
	}

	// Проверка срока жизни
	if time.Now().After(rec.ExpiresAt) {
		// Ключ просрочен -> удаляем (Lazy Eviction)
		delete(db.table, key)
		fmt.Printf(" -> [Database Lazy GC] Key '%s' has expired (ExpiresAt=%v)! Evicted.\n",
			key, rec.ExpiresAt.Format("15:04:05"))
		return "", false
	}

	return rec.ResponseJSON, true
}

func main() {
	db := NewDatabaseWithTTL()
	_ = context.Background()

	key := "uuid-payment-exp-001"
	resp := `{"status": "PAID", "amount": 5000}`

	// Сохраняем ключ с коротким TTL 40ms для теста
	fmt.Println("=== 1. Saving key with 40ms TTL ===")
	db.Save(key, resp, 40*time.Millisecond)

	// Немедленная выборка
	val, ok := db.GetActive(key)
	fmt.Printf("Immediate Lookup -> Found: %t, Body: %s\n\n", ok, val)

	// Ожидание истечения TTL
	fmt.Println("=== 2. Sleeping 60ms to let key expire ===")
	time.Sleep(60 * time.Millisecond)

	valAfter, okAfter := db.GetActive(key)
	fmt.Printf("Lookup After Expiration -> Found: %t (Key successfully expired!)\n", okAfter)
}

package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

type KeyItem struct {
	Key       string
	ExpiresAt time.Time
}

type TableStorage struct {
	mu    sync.Mutex
	items map[string]KeyItem
}

func (s *TableStorage) DeleteExpiredChunk(limit int) int {
	s.mu.Lock()
	defer s.mu.Unlock()

	now := time.Now()
	deleted := 0

	for k, item := range s.items {
		if item.ExpiresAt.Before(now) {
			delete(s.items, k)
			deleted++
			if deleted >= limit {
				break
			}
		}
	}
	return deleted
}

type CleanerJob struct {
	store    *TableStorage
	ticker   *time.Ticker
	stopChan chan struct{}
}

func NewCleanerJob(store *TableStorage, interval time.Duration) *CleanerJob {
	return &CleanerJob{
		store:    store,
		ticker:   time.NewTicker(interval),
		stopChan: make(chan struct{}),
	}
}

func (j *CleanerJob) Start(ctx context.Context) {
	go func() {
		fmt.Println("[Cleaner Daemon] Started periodic cleanup...")
		for {
			select {
			case <-ctx.Done():
				return
			case <-j.stopChan:
				return
			case <-j.ticker.C:
				total := 0
				for {
					n := j.store.DeleteExpiredChunk(2) // Пачками по 2
					total += n
					if n < 2 {
						break
					}
				}
				if total > 0 {
					fmt.Printf("[Cleaner Daemon] Purged %d expired idempotency keys.\n", total)
				}
			}
		}
	}()
}

func (j *CleanerJob) Stop() {
	j.ticker.Stop()
	close(j.stopChan)
}

func main() {
	store := &TableStorage{items: make(map[string]KeyItem)}
	now := time.Now()

	// 3 просроченных ключа
	for i := 1; i <= 3; i++ {
		k := fmt.Sprintf("expired-key-%d", i)
		store.items[k] = KeyItem{Key: k, ExpiresAt: now.Add(-1 * time.Hour)}
	}

	// 2 активных ключа
	for i := 1; i <= 2; i++ {
		k := fmt.Sprintf("active-key-%d", i)
		store.items[k] = KeyItem{Key: k, ExpiresAt: now.Add(2 * time.Hour)}
	}

	fmt.Printf("Initial table size: %d keys\n", len(store.items))

	cleaner := NewCleanerJob(store, 20*time.Millisecond)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	cleaner.Start(ctx)

	time.Sleep(50 * time.Millisecond)
	cleaner.Stop()

	fmt.Printf("Final table size: %d keys (Only active keys preserved!)\n", len(store.items))
}

